files.content:
.ta-vie-feature {
  --feature-max: 1240px;
  display: block;
  padding-block: var(--feature-PT, 64px) var(--feature-PB, 80px);
  background: var(--bg, var(--COLOR-BG));
  color: var(--text, var(--COLOR-TEXT));
}

.ta-vie-feature__inner {
  width: min(100% - 80px, var(--feature-max));
  margin-inline: auto;
}

.ta-vie-feature__intro {
  max-width: 760px;
  margin-bottom: 48px;
}

.ta-vie-feature__intro-heading {
  margin: 0;
  font-family: var(--FONT-STACK-HEADING);
  font-weight: var(--FONT-WEIGHT-HEADING);
  font-size: clamp(30px, 3.1vw, 46px);
  line-height: 1.5;
  text-wrap: balance;
  text-transform: none;
  overflow-wrap: anywhere;
}

.ta-vie-feature--wide {
  --feature-max: 1520px;
}

.ta-vie-feature__nav {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 28px;
  padding-bottom: 28px;
  margin-bottom: clamp(48px, 6vw, 88px);
  border-bottom: 1px solid var(--border, var(--COLOR-BORDER));
}

.ta-vie-feature__nav a {
  display: inline-flex;
  align-items: center;
  min-height: 44px;
  font-size: 13px;
  line-height: 1.6;
  text-underline-offset: 5px;
}

.ta-vie-feature__chapter {
  scroll-margin-top: calc(var(--header-height, 80px) + 32px);
}

.ta-vie-feature__chapter + .ta-vie-feature__chapter {
  margin-top: clamp(80px, 10vw, 152px);
}

.ta-vie-feature__eyebrow {
  margin: 0 0 14px;
  font-size: 12px;
  line-height: 1.6;
  letter-spacing: 0.08em;
}

.ta-vie-feature__heading {
  margin: 0 0 28px;
  font-family: var(--FONT-STACK-HEADING);
  font-weight: var(--FONT-WEIGHT-HEADING);
  font-size: clamp(25px, 2.7vw, 38px);
  line-height: 1.55;
  text-wrap: balance;
  text-transform: none;
  line-break: strict;
  overflow-wrap: anywhere;
}

.ta-vie-feature__split {
  display: grid;
  grid-template-columns: minmax(0, 1.35fr) minmax(0, 1fr);
  gap: clamp(32px, 6vw, 88px);
  align-items: start;
}

.ta-vie-feature__split--text-only {
  display: block;
  max-width: 720px;
}

.ta-vie-feature__split--media-only {
  display: block;
  max-width: 900px;
}

.ta-vie-feature__copy {
  min-width: 0;
  max-width: 38em;
  font-size: 16px;
  line-height: 1.95;
  line-break: strict;
  overflow-wrap: anywhere;
}

.ta-vie-feature__copy > :first-child,
.ta-vie-feature__copy .metafield-rich_text_field > :first-child {
  margin-top: 0;
}

.ta-vie-feature__copy > :last-child,
.ta-vie-feature__copy .metafield-rich_text_field > :last-child {
  margin-bottom: 0;
}

.ta-vie-feature__copy p + p {
  margin-top: 1.25em;
}

.ta-vie-feature__copy img,
.ta-vie-feature__copy video {
  max-width: 100%;
  height: auto;
}

.ta-vie-feature__copy a {
  text-decoration: underline;
  text-underline-offset: 4px;
}

.ta-vie-feature__media {
  position: relative;
  min-width: 0;
  margin: 0;
  overflow: hidden;
}

.ta-vie-feature__media[hidden],
.ta-vie-feature__chapter[hidden],
.ta-vie-feature__media video[hidden],
.ta-vie-feature__nav a[hidden] {
  display: none;
}

.ta-vie-feature__media img,
.ta-vie-feature__video {
  display: block;
  width: 100%;
}

.ta-vie-feature__media .image-wrapper {
  display: block;
  margin: 0;
}

.ta-vie-feature__media picture {
  display: block;
}

.ta-vie-feature--cover .ta-vie-feature__media picture {
  position: relative;
  aspect-ratio: var(--feature-image-ratio, 4 / 5);
}

.ta-vie-feature--cover .ta-vie-feature__media picture img {
  position: absolute;
  inset: 0;
  height: 100%;
}

.ta-vie-feature--cover .ta-vie-feature__media img {
  object-fit: cover;
}

.ta-vie-feature--contain .ta-vie-feature__media img {
  object-fit: contain;
}

.ta-vie-feature--contain .ta-vie-feature__media picture img {
  height: auto;
}

.ta-vie-feature__video {
  height: auto;
  max-height: 800px;
  object-fit: contain;
}

.ta-vie-feature__tab-list {
  display: none;
}

.ta-vie-feature__tabs[data-feature-enhanced] .ta-vie-feature__tab-list {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 24px;
  margin-bottom: 32px;
  border-bottom: 1px solid var(--border, var(--COLOR-BORDER));
}

.ta-vie-feature__tab {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 48px;
  margin: 0;
  padding: 10px 3px 12px;
  border: 0;
  border-bottom: 2px solid transparent;
  border-radius: 0;
  background: transparent;
  color: inherit;
  font: inherit;
  font-size: 14px;
  line-height: 1.6;
  text-align: center;
  cursor: pointer;
}

.ta-vie-feature__tab[aria-selected="true"] {
  border-bottom-color: currentColor;
}

.ta-vie-feature__panel[hidden] {
  display: none;
}

.ta-vie-feature__panel + .ta-vie-feature__panel {
  margin-top: 48px;
}

.ta-vie-feature__tabs[data-feature-enhanced] .ta-vie-feature__panel {
  margin-top: 0;
}

.ta-vie-feature__panel-content h3 {
  margin-top: 0;
  margin-bottom: 20px;
  font-family: var(--FONT-STACK-HEADING);
  font-weight: var(--FONT-WEIGHT-HEADING);
  font-size: clamp(20px, 2vw, 27px);
  line-height: 1.6;
}

.ta-vie-feature__accordion {
  border-bottom: 1px solid var(--border, var(--COLOR-BORDER));
}

.ta-vie-feature__accordion:first-child {
  border-top: 1px solid var(--border, var(--COLOR-BORDER));
}

.ta-vie-feature__accordion summary {
  display: list-item;
  min-height: 56px;
  padding-block: 18px;
  font-size: 16px;
  line-height: 1.6;
  cursor: pointer;
}

.ta-vie-feature__accordion .ta-vie-feature__copy {
  padding-block: 4px 24px;
}

.ta-vie-feature__table-wrap {
  max-width: 100%;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}

.ta-vie-feature__table {
  width: 100%;
  min-width: 480px;
  border-collapse: collapse;
  font-size: 14px;
  line-height: 1.7;
  text-align: left;
}

.ta-vie-feature__table caption {
  padding-bottom: 16px;
  text-align: left;
}

.ta-vie-feature__copy + .ta-vie-feature__table-wrap {
  margin-top: 28px;
}

.ta-vie-feature__table th,
.ta-vie-feature__table td {
  padding: 16px 20px;
  border-bottom: 1px solid var(--border, var(--COLOR-BORDER));
  white-space: nowrap;
}

.ta-vie-feature__table th {
  font-weight: 500;
}

.ta-vie-feature__purchase {
  max-width: 720px;
  padding-top: 32px;
  border-top: 1px solid var(--border, var(--COLOR-BORDER));
}

.ta-vie-feature__purchase .btn {
  min-height: 48px;
  margin-top: 24px;
}

.ta-vie-feature__editor-note {
  margin-block: 24px;
  padding: 16px 20px;
  border-left: 2px solid currentColor;
  font-size: 14px;
  line-height: 1.8;
}

.ta-vie-feature :is(a, button, summary, [tabindex="0"]):focus-visible {
  outline: 2px solid currentColor;
  outline-offset: 5px;
}

@media (min-width: 990px) and (prefers-reduced-motion: no-preference) {
  .ta-vie-feature--sticky .ta-vie-feature__split > .ta-vie-feature__media {
    position: sticky;
    top: calc(var(--header-height, 80px) + 32px);
  }

  .ta-vie-feature[data-feature-motion="true"] .ta-vie-feature__media img {
    transition: transform 8s ease-out;
  }

  .ta-vie-feature--cover[data-feature-motion="true"] .ta-vie-feature__media[data-feature-in-view] img {
    transform: scale(1.035);
  }
}

@media (max-width: 989px) {
  .ta-vie-feature__inner {
    width: calc(100% - 48px);
  }

  .ta-vie-feature__split {
    grid-template-columns: minmax(0, 1fr);
    gap: 28px;
  }

  .ta-vie-feature__copy {
    max-width: 44em;
  }
}

@media (max-width: 749px) {
  .ta-vie-feature {
    padding-block: min(var(--feature-PT, 64px), 56px) min(var(--feature-PB, 80px), 72px);
  }

  .ta-vie-feature__inner {
    width: calc(100% - 40px);
  }

  .ta-vie-feature__nav {
    gap: 4px 20px;
    padding-bottom: 20px;
    margin-bottom: 48px;
  }

  .ta-vie-feature__chapter + .ta-vie-feature__chapter {
    margin-top: 72px;
  }

  .ta-vie-feature__heading {
    margin-bottom: 24px;
  }

  .ta-vie-feature__copy {
    font-size: 15px;
    line-height: 1.95;
  }

  .ta-vie-feature--cover .ta-vie-feature__media picture {
    aspect-ratio: var(--feature-mobile-image-ratio, var(--feature-image-ratio, 4 / 5));
  }

  .ta-vie-feature__tabs[data-feature-enhanced] .ta-vie-feature__tab-list {
    gap: 4px 20px;
    margin-bottom: 24px;
  }

  .ta-vie-feature__tab {
    min-height: 48px;
  }

  .ta-vie-feature__table th,
  .ta-vie-feature__table td {
    padding: 14px 16px;
  }

  .ta-vie-feature__purchase .btn {
    width: 100%;
  }
}

@media (prefers-reduced-motion: reduce) {
  .ta-vie-feature *,
  .ta-vie-feature *::before,
  .ta-vie-feature *::after {
    scroll-behavior: auto;
    animation: none;
    transition: none;
  }
}

(() => {
  if (customElements.get('ta-vie-product-feature')) return;

  class TaVieProductFeature extends HTMLElement {
    connectedCallback() {
      if (this.cleanup) return;
      this.cleanup = [];
      this.groups = [];
      this.motion = window.matchMedia('(prefers-reduced-motion: reduce)');
      this.querySelectorAll('[data-feature-tabs]').forEach((group) => this.setupTabs(group));
      this.setupMediaFallbacks();
      this.onClick = (event) => this.returnToPurchase(event);
      this.addEventListener('click', this.onClick);
      this.onMotionChange = () => this.setupMotion();
      this.motion.addEventListener('change', this.onMotionChange);
      this.setupMotion();
    }

    disconnectedCallback() {
      this.removeEventListener('click', this.onClick);
      this.motion?.removeEventListener('change', this.onMotionChange);
      this.observer?.disconnect();
      this.observer = null;
      this.querySelectorAll('video').forEach((video) => video.pause());
      this.cleanup?.slice().reverse().forEach((restore) => restore());
      this.cleanup = null;
      this.groups = [];
    }

    saveAttributes(element, names) {
      const original = names.map((name) => [name, element.getAttribute(name)]);
      this.cleanup.push(() => original.forEach(([name, value]) => {
        if (value === null) element.removeAttribute(name);
        else element.setAttribute(name, value);
      }));
    }

    setupTabs(group) {
      const tabs = [...group.querySelectorAll('[data-feature-tab]')]
        .filter((tab) => tab.closest('[data-feature-tabs]') === group && !tab.disabled);
      const panels = tabs.map((tab) => document.getElementById(tab.getAttribute('aria-controls')));
      if (!tabs.length || tabs.some((tab) => !tab.id) || panels.some((panel) => !panel || !group.contains(panel)) || new Set(panels).size !== panels.length) return;
      const tabList = group.querySelector('[data-feature-tab-list]');
      if (!tabList || tabs.some((tab) => !tabList.contains(tab))) return;

      this.saveAttributes(group, ['data-feature-enhanced']);
      this.saveAttributes(tabList, ['role', 'aria-orientation']);
      tabList.setAttribute('role', 'tablist');
      tabList.setAttribute('aria-orientation', 'horizontal');
      tabs.forEach((tab, index) => {
        this.saveAttributes(tab, ['role', 'aria-selected', 'tabindex']);
        this.saveAttributes(panels[index], ['role', 'aria-labelledby', 'tabindex', 'hidden']);
        tab.setAttribute('role', 'tab');
        panels[index].setAttribute('role', 'tabpanel');
        panels[index].setAttribute('aria-labelledby', tab.id);
        panels[index].setAttribute('tabindex', '0');
      });
      const select = (index, focus = false) => {
        tabs.forEach((tab, candidate) => {
          const active = candidate === index;
          tab.setAttribute('aria-selected', String(active));
          tab.tabIndex = active ? 0 : -1;
          panels[candidate].hidden = !active;
          if (!active) panels[candidate].querySelectorAll('video').forEach((video) => video.pause());
        });
        if (focus) tabs[index].focus({preventScroll: true});
      };
      const onClick = (event) => {
        const tab = event.target.closest('[data-feature-tab]');
        const index = tabs.indexOf(tab);
        if (index < 0) return;
        event.preventDefault();
        select(index);
      };
      const onKeyDown = (event) => {
        const index = tabs.indexOf(event.target.closest('[data-feature-tab]'));
        if (index < 0) return;
        let next;
        if (event.key === 'ArrowRight' || event.key === 'ArrowDown') next = (index + 1) % tabs.length;
        else if (event.key === 'ArrowLeft' || event.key === 'ArrowUp') next = (index - 1 + tabs.length) % tabs.length;
        else if (event.key === 'Home') next = 0;
        else if (event.key === 'End') next = tabs.length - 1;
        else return;
        event.preventDefault();
        select(next, true);
      };
      group.addEventListener('click', onClick);
      group.addEventListener('keydown', onKeyDown);
      this.cleanup.push(() => {
        group.removeEventListener('click', onClick);
        group.removeEventListener('keydown', onKeyDown);
      });
      select(0);
      group.setAttribute('data-feature-enhanced', '');
      this.groups.push(group);
    }

    setupMotion() {
      this.observer?.disconnect();
      this.observer = null;
      this.querySelectorAll('[data-feature-in-view]').forEach((media) => media.removeAttribute('data-feature-in-view'));
      if (this.motion.matches || this.dataset.featureMotion !== 'true' || !('IntersectionObserver' in window)) return;
      this.observer = new IntersectionObserver((entries) => {
        entries.forEach((entry) => {
          if (!entry.isIntersecting) return;
          entry.target.setAttribute('data-feature-in-view', '');
          this.observer?.unobserve(entry.target);
        });
      }, {threshold: 0.2});
      this.querySelectorAll('.ta-vie-feature__media:not(.ta-vie-feature__media--video)').forEach((media) => this.observer.observe(media));
    }

    setupMediaFallbacks() {
      this.querySelectorAll('.ta-vie-feature__media').forEach((media) => {
        const split = media.closest('.ta-vie-feature__split');
        const chapter = media.closest('.ta-vie-feature__chapter');
        this.saveAttributes(media, ['hidden']);
        if (split) this.saveAttributes(split, ['class']);
        if (chapter) this.saveAttributes(chapter, ['hidden']);
        const hide = () => {
          media.hidden = true;
          if (split?.querySelector('.ta-vie-feature__copy')) split.classList.add('ta-vie-feature__split--text-only');
          else if (chapter) {
            chapter.hidden = true;
            this.querySelectorAll('.ta-vie-feature__nav a').forEach((link) => {
              if (link.getAttribute('href') !== `#${chapter.id}`) return;
              this.saveAttributes(link, ['hidden']);
              link.hidden = true;
            });
          }
        };
        const watchImage = (image) => {
          image.addEventListener('error', hide, {once: true});
          this.cleanup.push(() => image.removeEventListener('error', hide));
          if (image.complete && image.currentSrc && !image.naturalWidth) hide();
        };
        media.querySelectorAll('img').forEach(watchImage);
        media.querySelectorAll('video').forEach((video) => {
          const fallback = () => {
            if (!video.poster) { hide(); return; }
            const image = document.createElement('img');
            image.alt = '';
            watchImage(image);
            image.src = video.poster;
            media.append(image);
            this.saveAttributes(video, ['hidden']);
            video.hidden = true;
            video.pause();
            this.cleanup.push(() => image.remove());
          };
          video.addEventListener('error', fallback, {once: true});
          this.cleanup.push(() => video.removeEventListener('error', fallback));
          if (video.error) {
            video.removeEventListener('error', fallback);
            fallback();
          }
        });
      });
    }

    returnToPurchase(event) {
      const link = event.target.closest('[data-feature-purchase]');
      if (!link || !this.contains(link) || event.defaultPrevented || event.button !== 0 || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return;
      const href = link.getAttribute('href');
      if (!href?.startsWith('#')) return;
      let target;
      try { target = document.getElementById(decodeURIComponent(href.slice(1))); } catch { return; }
      if (!target) return;
      const product = target.closest('product-info') || target.closest('.shopify-section')?.querySelector('product-info') || document.querySelector('product-info[id^="MainProduct--"]');
      if (!product) return;
      const candidates = [
        'variant-selects input:checked:not([type="hidden"]):not(:disabled)',
        'variant-selects select:not(:disabled)',
        'variant-selects button[data-popout-toggle]:not(:disabled)',
        'variant-selects input:not([type="hidden"]):not(:disabled)',
        '[data-product-form] [data-add-to-cart]:not(:disabled)',
      ].flatMap((selector) => [...product.querySelectorAll(selector)]);
      const control = candidates.find((candidate) => candidate.getClientRects().length && getComputedStyle(candidate).visibility !== 'hidden');
      event.preventDefault();
      target.scrollIntoView({behavior: this.motion.matches ? 'instant' : 'smooth', block: 'start'});
      if (control) control.focus({preventScroll: true});
      else {
        const fallback = product.querySelector('.product__title, h1') || product;
        if (!fallback.hasAttribute('tabindex')) {
          fallback.tabIndex = -1;
          const restore = () => {
            fallback.removeAttribute('tabindex');
            fallback.removeEventListener('blur', restore);
          };
          fallback.addEventListener('blur', restore, {once: true});
          this.cleanup.push(restore);
        }
        fallback.focus({preventScroll: true});
      }
    }
  }

  customElements.define('ta-vie-product-feature', TaVieProductFeature);
})();

/* Small, opt-in additions to the original Broadcast purchase layout. */
[data-ta-vie-experience="true"] .product__title {
  line-height: 1.45;
  letter-spacing: .035em;
  overflow-wrap: anywhere;
}
.ta-vie-purchase__intro {
  max-width: 34em;
  font-size: clamp(1rem, .94rem + .2vw, 1.125rem);
  line-height: 1.9;
  letter-spacing: .035em;
}
.ta-vie-purchase__intro p { margin: 0; }
.ta-vie-purchase__anchor {
  display: block;
  scroll-margin-top: calc(var(--header-height, 80px) + 24px);
}
.ta-vie-purchase__editor-note {
  padding: 12px;
  border: 1px dashed currentColor;
  font-size: .875rem;
  line-height: 1.8;
}
[data-ta-vie-experience="true"] .product__selectors label,
[data-ta-vie-experience="true"] .product__submit__add { min-height: 44px; }
[data-ta-vie-experience="true"] .product__block--accordion .rte { line-height: 1.85; }
[data-ta-vie-experience="true"][data-product-media-count="0"] .product__images { display: none; }
[data-ta-vie-experience="true"][data-product-media-count="0"] .product__page { grid-template-columns: minmax(0, 1fr); }
[data-ta-vie-experience="true"][data-product-media-count="0"] .product__content {
  width: 100%;
  max-width: 44rem;
  margin-inline: auto;
}
[data-ta-vie-experience="true"] [id^="Price-"][hidden] { display: none; }
[data-ta-vie-experience="true"] [data-add-to-cart] [data-product-price][hidden] { display: none; }
[data-ta-vie-purchase-bar] .cart-bar__info {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  column-gap: 24px;
  row-gap: 2px;
  flex: 1;
}
[data-ta-vie-purchase-bar] .cart-bar__product__title {
  font-size: 1rem;
  line-height: 1.5;
}
[data-ta-vie-purchase-bar] .cart-bar__product__price {
  grid-column: 2;
  grid-row: 1 / 3;
  padding: 0;
}
[data-ta-vie-purchase-bar] .cart-bar__product__price::before { display: none; }
[data-ta-vie-purchase-bar] .cart-bar__product__price[hidden] { display: none; }
.ta-vie-purchase__selection {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 16px;
  line-height: 1.5;
}
[data-ta-vie-purchase-bar] .cart-bar__form { margin-left: 24px; }
@media (max-width: 749px) {
  [data-ta-vie-purchase-bar] .cart-bar__info {
    text-align: left;
    padding: 0;
    column-gap: 12px;
    margin-bottom: 8px;
  }
  [data-ta-vie-purchase-bar] .cart-bar__product__title { font-size: .875rem; }
  .ta-vie-purchase__selection { font-size: .75rem; gap: 2px 8px; }
  [data-ta-vie-purchase-bar] .cart-bar__form { margin-left: 0; }
  [data-ta-vie-purchase-bar] .cart-bar__form__wrapper {
    padding-bottom: max(10px, env(safe-area-inset-bottom));
  }
}
@media (prefers-reduced-motion: reduce) {
  [data-ta-vie-experience="true"] .product__images *,
  [data-ta-vie-purchase-bar] { animation: none !important; transition: none !important; }
}

/* The native ProductInfo replaces the bar for every real variant. Its
 * unavailable-combination path emits only the form's hidden-id change; handle
 * that path without replacing Broadcast's selection or purchase logic. */
if (!customElements.get('ta-vie-purchase-state')) {
  // Broadcast serializes fetched product HTML during a whole-page swap. Keep
  // the notification contact form outside the purchase form before that
  // serialization, so the browser does not discard a nested form on reparse.
  const preparedProducts = new WeakSet();
  const prepareProductSwap = (productInfo) => {
    if (productInfo?.dataset.taVieExperience !== 'true' || preparedProducts.has(productInfo)) return;
    if (typeof productInfo.addPreProcessCallback !== 'function') return;
    preparedProducts.add(productInfo);
    productInfo.addPreProcessCallback((html) => {
      // A different product also needs its own canonical and sharing metadata.
      // Section-only variant responses have no full page head and stay native.
      const fetchedHead = html.ownerDocument.head;
      if (html.matches('main') && fetchedHead?.querySelector('link[rel="canonical"]')) {
        const metadata = 'link[rel="canonical"], meta[name="description"], meta[property^="og:"], meta[name^="twitter:"]';
        document.head.querySelectorAll(metadata).forEach((node) => node.remove());
        fetchedHead.querySelectorAll(metadata).forEach((node) => document.head.append(node.cloneNode(true)));
      }
      html.querySelectorAll('popup-component.product-soldout-notification').forEach((popup) => {
        const purchaseForm = popup.closest('form[data-product-form]');
        if (purchaseForm) purchaseForm.after(popup);
      });
    });
  };
  document.addEventListener('theme:product-info:loaded', (event) => prepareProductSwap(event.target));
  customElements.whenDefined('product-info').then(() => {
    document.querySelectorAll('product-info').forEach(prepareProductSwap);
  });

  customElements.define('ta-vie-purchase-state', class extends HTMLElement {
    connectedCallback() {
      this.productInfo = this.closest('product-info');
      this.onVariantInput = (event) => {
        if (!event.target.matches('input[name="id"]') || event.target.form?.getAttribute('id') !== `product-form-${this.productInfo?.dataset.section}`) return;
        queueMicrotask(() => {
          if (this.isConnected) this.updateUnavailable();
        });
      };
      this.productInfo?.addEventListener('change', this.onVariantInput);
      this.updateUnavailable();
    }

    disconnectedCallback() {
      this.productInfo?.removeEventListener('change', this.onVariantInput);
    }

    updateUnavailable() {
      const input = this.productInfo?.querySelector(`#product-form-${CSS.escape(this.productInfo.dataset.section)} input[name="id"]`);
      if (!input) return;
      const mainPrice = this.productInfo.querySelector(`#Price-${CSS.escape(this.productInfo.dataset.section)}`);
      if (mainPrice) mainPrice.hidden = !input.value;
      const buttonPrice = this.productInfo.querySelector('[data-add-to-cart] [data-product-price]');
      if (buttonPrice) buttonPrice.hidden = !input.value;
      if (input.value) return;
      const bar = this.closest('cart-bar');
      const selected = this.querySelector('[data-ta-vie-selected-variant]');
      if (selected) {
        const selector = this.productInfo.querySelector('variant-selects');
        selected.textContent = Array.from(selector?.querySelectorAll('[data-selected-value]') || [])
          .map((value) => value.textContent.trim()).filter(Boolean).join(' / ');
      }
      const status = this.querySelector('[data-ta-vie-availability]');
      if (status) status.textContent = window.theme?.strings?.unavailable || '選択できません';
      const price = bar?.querySelector('.cart-bar__product__price');
      if (price) price.hidden = true;
    }
  });
}

.ta-vie-product-stories {
  background: var(--COLOR-BG);
  color: var(--COLOR-TEXT);
}

.ta-vie-product-stories > .wrapper--full-padded {
  max-width: 1600px;
  margin-inline: auto;
}

.ta-vie-product-stories__intro {
  max-width: 760px;
  margin: 0 0 clamp(40px, 6vw, 88px);
}

.ta-vie-product-stories__eyebrow,
.ta-vie-product-story__eyebrow {
  margin: 0 0 16px;
  font-size: 12px;
  line-height: 1.6;
  letter-spacing: 0.08em;
}

.ta-vie-product-stories__heading,
.ta-vie-product-story__title,
.ta-vie-product-story__detail-heading {
  margin: 0;
  font-family: var(--FONT-STACK-HEADING);
  font-weight: var(--FONT-WEIGHT-HEADING);
  line-break: strict;
  overflow-wrap: anywhere;
  word-break: normal;
  text-wrap: balance;
}

.ta-vie-product-stories__heading {
  font-size: clamp(32px, 3.4vw, 54px);
  line-height: 1.4;
}

.ta-vie-product-stories__intro-copy {
  max-width: 36em;
  margin-top: 20px;
}

.ta-vie-product-story + .ta-vie-product-story {
  margin-top: clamp(88px, 12vw, 176px);
}

.ta-vie-product-story__stage,
.ta-vie-product-story__detail {
  display: grid;
  grid-template-columns: minmax(0, 1.75fr) minmax(0, 1fr);
  gap: clamp(36px, 6vw, 88px);
  align-items: center;
}

.ta-vie-product-story__media,
.ta-vie-product-story__scene-image,
.ta-vie-product-story__detail-media {
  position: relative;
  min-width: 0;
  overflow: hidden;
  background: var(--COLOR-BG-ACCENT);
}

.ta-vie-product-story__media {
  width: 100%;
  aspect-ratio: 4 / 5;
  max-height: 980px;
}

.ta-vie-product-story__image {
  height: 100%;
  margin: 0;
  padding-top: 0;
}

.ta-vie-product-story__media > .desktop,
.ta-vie-product-story__media > .mobile {
  height: 100%;
}

.ta-vie-product-story__media--contain img {
  object-fit: contain;
}

.ta-vie-product-story__media--cover img,
.ta-vie-product-story__scene-image img,
.ta-vie-product-story__detail-media img {
  object-fit: cover;
}

.ta-vie-product-story__copy {
  min-width: 0;
  max-width: 420px;
  padding-block: 24px;
}

.ta-vie-product-story__title {
  font-size: clamp(28px, 3vw, 44px);
  line-height: 1.45;
}

.ta-vie-product-stories__intro-copy,
.ta-vie-product-story__intro,
.ta-vie-product-story__detail-text,
.ta-vie-product-story__caption {
  font-size: 16px;
  line-height: 1.85;
  overflow-wrap: anywhere;
}

.ta-vie-product-story__intro {
  margin-top: 24px;
}

.ta-vie-product-story__intro > :first-child,
.ta-vie-product-story__detail-text > :first-child,
.ta-vie-product-story__caption > :first-child,
.ta-vie-product-stories__intro-copy > :first-child {
  margin-top: 0;
}

.ta-vie-product-story__intro > :last-child,
.ta-vie-product-story__detail-text > :last-child,
.ta-vie-product-story__caption > :last-child,
.ta-vie-product-stories__intro-copy > :last-child {
  margin-bottom: 0;
}

.ta-vie-product-story__intro img,
.ta-vie-product-story__detail-text img {
  max-width: 100%;
  height: auto;
}

.ta-vie-product-story__price {
  margin-top: 28px;
  font-size: 16px;
}

.ta-vie-product-story__button {
  margin-top: 24px;
}

.ta-vie-product-story__scene {
  margin: clamp(40px, 7vw, 104px) 0 0;
}

.ta-vie-product-story__scene-image {
  aspect-ratio: 16 / 10;
  height: auto;
  margin: 0;
  padding-top: 0;
}

.ta-vie-product-story__caption {
  max-width: 40em;
  margin: 16px 0 0;
}

.ta-vie-product-story__detail {
  max-width: 1240px;
  margin: clamp(40px, 7vw, 104px) auto 0;
  grid-template-columns: minmax(0, 1.2fr) minmax(0, 1fr);
}

.ta-vie-product-story__detail-media {
  aspect-ratio: 1;
}

.ta-vie-product-story__detail--image-only {
  display: block;
  max-width: 720px;
}

.ta-vie-product-story__detail-copy {
  min-width: 0;
  max-width: 400px;
}

.ta-vie-product-story__detail-heading {
  font-size: clamp(24px, 2vw, 32px);
  line-height: 1.5;
}

.ta-vie-product-story__detail-text {
  margin-top: 20px;
}

.ta-vie-product-story--text-only .ta-vie-product-story__stage {
  grid-template-columns: minmax(0, 1fr);
}

.ta-vie-product-stories__editor-note {
  margin-block: 32px;
  padding: 24px;
  border: 1px solid var(--COLOR-BORDER);
  background: var(--COLOR-BG-ACCENT);
  font-size: 16px;
  line-height: 1.8;
}

.ta-vie-product-stories__all-link {
  margin-top: clamp(56px, 8vw, 112px);
  text-align: center;
}

@media only screen and (min-width: 990px) {
  .ta-vie-product-story--image-right .ta-vie-product-story__stage {
    grid-template-columns: minmax(0, 1fr) minmax(0, 1.75fr);
  }

  .ta-vie-product-story--image-right .ta-vie-product-story__media {
    grid-column: 2;
    grid-row: 1;
  }

  .ta-vie-product-story--image-right .ta-vie-product-story__copy {
    grid-column: 1;
    grid-row: 1;
  }

  .ta-vie-product-story--text-only .ta-vie-product-story__stage {
    grid-template-columns: minmax(0, 1fr);
  }

  .ta-vie-product-story--text-only .ta-vie-product-story__copy {
    grid-column: 1;
  }

  .ta-vie-product-story__detail--image-right {
    grid-template-columns: minmax(0, 1fr) minmax(0, 1.2fr);
  }

  .ta-vie-product-story__detail--image-right .ta-vie-product-story__detail-media {
    grid-column: 2;
    grid-row: 1;
  }

  .ta-vie-product-story__detail--image-right .ta-vie-product-story__detail-copy {
    grid-column: 1;
    grid-row: 1;
  }
}

@media only screen and (max-width: 989px) {
  .ta-vie-product-story__stage,
  .ta-vie-product-story__detail {
    grid-template-columns: minmax(0, 1fr);
    gap: 24px;
  }

  .ta-vie-product-story__copy {
    padding-block: 8px;
  }

  .ta-vie-product-story__scene-image {
    aspect-ratio: 4 / 5;
  }
}

