    },
    {
      "type": "text",
      "id": "all_label",
      "label": "全商品リンクのテキスト",
      "default": "全商品を見る"
    },
    {
      "type": "range",
      "id": "padding_top",
      "label": "上の余白",
      "min": 0,
      "max": 200,
      "step": 2,
      "unit": "px",
      "default": 80
    },
    {
      "type": "range",
      "id": "padding_bottom",
      "label": "下の余白",
      "min": 0,
      "max": 200,
      "step": 2,
      "unit": "px",
      "default": 80
    }
  ],
  "max_blocks": 6,
  "blocks": [
    {
      "type": "product_story",
      "name": "商品を紹介",
      "settings": [
        {
          "type": "product",
          "id": "product",
          "label": "紹介する商品"
        },
        {
          "type": "text",
          "id": "eyebrow",
          "label": "小見出し"
        },
        {
          "type": "richtext",
          "id": "intro",
          "label": "商品の紹介文",
          "info": "素材や仕様の説明は、確認できる内容を記入してください。"
        },
        {
          "type": "checkbox",
          "id": "use_product_description",
          "label": "紹介文が空なら商品説明を使用",
          "info": "オンの場合のみ、空欄の紹介文に登録済みの商品説明を表示します。",
          "default": false
        },
        {
          "type": "image_picker",
          "id": "main_image",
          "label": "メイン写真",
          "info": "空欄の場合は、その商品のメイン写真を使います。"
        },
        {
          "type": "image_picker",
          "id": "mobile_main_image",
          "label": "メイン写真（スマートフォン）",
          "info": "空欄の場合は、メイン写真と同じ写真を使います。"
        },
        {
          "type": "select",
          "id": "image_fit",
          "label": "メイン写真の見せ方",
          "default": "contain",
          "options": [
            {"value": "contain", "label": "写真全体を見せる"},
            {"value": "cover", "label": "枠いっぱいに見せる"}
          ]
        },
        {
          "type": "select",
          "id": "image_position",
          "label": "メイン写真の位置（PC）",
          "default": "left",
          "options": [
            {"value": "left", "label": "左"},
            {"value": "right", "label": "右"}
          ]
        },
        {
          "type": "image_picker",
          "id": "scene_image",
          "label": "着用・暮らしの写真",
          "info": "この商品を着て過ごす様子など、ブランドの世界観を伝える写真を選びます。未設定の場合、この部分は表示されません。"
        },
        {
          "type": "image_picker",
          "id": "mobile_scene_image",
          "label": "着用・暮らしの写真（スマートフォン）"
        },
        {
          "type": "richtext",
          "id": "scene_caption",
          "label": "着用・暮らしの写真の説明"
        },
        {
          "type": "image_picker",
          "id": "detail_image",
          "label": "細部の写真",
          "info": "生地、縫い目、シルエットなどを紹介する写真を選びます。未設定の場合、この部分は表示されません。"
        },
        {
          "type": "text",
          "id": "detail_heading",
          "label": "細部の見出し"
        },
        {
          "type": "richtext",
          "id": "detail_text",
          "label": "細部の説明"
        },
        {
          "type": "text",
          "id": "button_label",
          "label": "商品ページへのリンクのテキスト",
          "default": "商品の詳細を見る"
        }
      ]
    }
  ],
  "presets": [
    {
      "name": "TA VIE｜商品を紹介",
      "category": "Products",
      "blocks": [
        {"type": "product_story"},
        {"type": "product_story", "settings": {"image_position": "right"}}
      ]
    }
  ],
  "disabled_on": {
    "groups": ["header", "aside", "custom.pre_footer", "footer"]
  }
}
{% endschema %}

