files.content:
{%- comment -%}
  Size values include the merchant's own units. Empty / foreign-product rows
  and entirely empty measurement columns are omitted.
{%- endcomment -%}
{%- liquid
  assign feature_size_count = 0
  assign feature_table_label = table_label | default: '商品実寸'
  assign size_length = false
  assign size_chest = false
  assign size_sleeve = false
  assign size_waist = false
  assign size_inseam = false
  for row in rows
    if product.id != blank and row.owner_product.value.id == product.id and row.label.value != blank and feature_size_count < 12
      if row.length.value != blank or row.chest.value != blank or row.sleeve.value != blank or row.waist.value != blank or row.inseam.value != blank
        assign feature_size_count = feature_size_count | plus: 1
        if row.length.value != blank
          assign size_length = true
        endif
        if row.chest.value != blank
          assign size_chest = true
        endif
        if row.sleeve.value != blank
          assign size_sleeve = true
        endif
        if row.waist.value != blank
          assign size_waist = true
        endif
        if row.inseam.value != blank
          assign size_inseam = true
        endif
      endif
    endif
  endfor
-%}
{%- if feature_size_count > 0 -%}
  <div class="ta-vie-feature__table-wrap" tabindex="0" role="region" aria-label="{{ feature_table_label | escape }}">
    <table class="ta-vie-feature__table">
      <caption>{{ feature_table_label | escape }}</caption>
      <thead>
        <tr>
          <th scope="col">サイズ</th>
          {%- if size_length -%}<th scope="col">着丈</th>{%- endif -%}
          {%- if size_chest -%}<th scope="col">身幅</th>{%- endif -%}
          {%- if size_sleeve -%}<th scope="col">袖丈</th>{%- endif -%}
          {%- if size_waist -%}<th scope="col">ウエスト</th>{%- endif -%}
          {%- if size_inseam -%}<th scope="col">股下</th>{%- endif -%}
        </tr>
      </thead>
      <tbody>
        {%- assign feature_size_count = 0 -%}
        {%- for row in rows -%}
          {%- if product.id != blank and row.owner_product.value.id == product.id and row.label.value != blank and feature_size_count < 12 -%}
            {%- if row.length.value != blank or row.chest.value != blank or row.sleeve.value != blank or row.waist.value != blank or row.inseam.value != blank -%}
              {%- assign feature_size_count = feature_size_count | plus: 1 -%}
              <tr>
                <th scope="row">{{ row.label.value | escape }}</th>
                {%- if size_length -%}<td>{{ row.length.value | default: '—' | escape }}</td>{%- endif -%}
                {%- if size_chest -%}<td>{{ row.chest.value | default: '—' | escape }}</td>{%- endif -%}
                {%- if size_sleeve -%}<td>{{ row.sleeve.value | default: '—' | escape }}</td>{%- endif -%}
                {%- if size_waist -%}<td>{{ row.waist.value | default: '—' | escape }}</td>{%- endif -%}
                {%- if size_inseam -%}<td>{{ row.inseam.value | default: '—' | escape }}</td>{%- endif -%}
              </tr>
            {%- endif -%}
          {%- endif -%}
        {%- endfor -%}
      </tbody>
    </table>
  </div>
{%- endif -%}

{%- if request.design_mode -%}
  <div class="wrapper section-padding" style="--PT: 24px; --PB: 24px;">
    <p class="body-small" role="status">{{ message | escape }}</p>
  </div>
{%- endif -%}

{%- if section.settings.ta_vie_hide_unconfigured -%}
  {%- style -%}
    @media (prefers-reduced-motion: reduce) {
      #shopify-section-{{ section.id }} [data-aos] {
        opacity: 1 !important;
        transform: none !important;
        transition: none !important;
        animation: none !important;
      }
      #shopify-section-{{ section.id }} [data-parallax-img],
      #shopify-section-{{ section.id }} .column__image img {
        transform: none !important;
        transition: none !important;
      }
      #shopify-section-{{ section.id }} .slideshow__slide { transition: none !important; }
    }
  {%- endstyle -%}
{%- endif -%}

{%- comment -%}
  Optional editorial typography in TA VIE's existing home sections only.
  Theme mode preserves native typography and only adjusts Japanese wrapping
  in the hero, text-with-products, image-with-text story and blog headings.
{%- endcomment -%}
{%- liquid
  assign ta_vie_heading_style = settings.ta_vie_home_heading_style | default: 'theme'
  unless ta_vie_heading_style == 'serif' or ta_vie_heading_style == 'sans'
    assign ta_vie_heading_style = 'theme'
  endunless
  assign ta_vie_heading_spacing = settings.ta_vie_home_heading_spacing | default: 5 | divided_by: 100.0
  assign ta_vie_body_line_height = settings.ta_vie_home_body_line_height | default: 1.9
  assign ta_vie_subheading_size = settings.ta_vie_home_subheading_size | default: 12
  assign ta_vie_body_family = settings.type_base_font.family | default: 'DM Sans'
  assign ta_vie_section_ids = 'section_slideshow_nested_YfkG44,section_text_with_products_yW3LJx,columns-1,double,custom-content-1,announcement-3,section_dynamic_content_TkrMUq,columns-2,section_hero_scrolling_mmThBz,ta_vie_products,ta_vie_reading' | split: ','
  assign ta_vie_wrap_section_ids = 'section_slideshow_nested_YfkG44,section_text_with_products_yW3LJx,double,ta_vie_reading' | split: ','
-%}

{%- capture ta_vie_sections -%}
  {%- for ta_vie_section_id in ta_vie_section_ids -%}
    {%- unless forloop.first -%},{%- endunless -%}
    [data-section-id="{{ ta_vie_section_id }}"],[data-section-id$="__{{ ta_vie_section_id }}"]
  {%- endfor -%}
{%- endcapture -%}
{%- capture ta_vie_scope -%}body.template-index #MainContent :is({{ ta_vie_sections }}){%- endcapture -%}
{%- capture ta_vie_wrap_sections -%}
  {%- for ta_vie_section_id in ta_vie_wrap_section_ids -%}
    {%- unless forloop.first -%},{%- endunless -%}
    [data-section-id="{{ ta_vie_section_id }}"],[data-section-id$="__{{ ta_vie_section_id }}"]
  {%- endfor -%}
{%- endcapture -%}
{%- capture ta_vie_wrap_scope -%}body.template-index #MainContent :is({{ ta_vie_wrap_sections }}){%- endcapture -%}

{%- style -%}
  {%- if ta_vie_heading_style == 'serif' or ta_vie_heading_style == 'sans' %}
  {{ ta_vie_scope }} :is(
    .hero__title,
    .column__heading,
    .text-products__heading,
    .grid__heading,
    .page__heading,
    .article__title,
    .announcement__slide .font-heading,
    .announcement__content
  ):not(.product-item, .product-item *, product-info, product-info *, .hero__products *, .hero__collections *) {
    {%- if ta_vie_heading_style == 'sans' %}
      font-family: {{ ta_vie_body_family | json }}, "Hiragino Kaku Gothic ProN", "Yu Gothic", Meiryo, "Noto Sans CJK JP", sans-serif;
    {%- else %}
      font-family: Georgia, "Times New Roman", "Yu Mincho", YuMincho, "Hiragino Mincho ProN", "Noto Serif CJK JP", serif;
    {%- endif %}
    font-weight: 400;
    font-style: normal;
    text-transform: none;
    letter-spacing: {{ ta_vie_heading_spacing }}em;
    line-height: 1.55;
    text-wrap: balance;
  }

  {{ ta_vie_scope }} :is(.hero__rte, .hero__description, .column__text, .article__excerpt):not(.product-item, .product-item *, product-info, product-info *, .hero__products *, .hero__collections *) {
    font-family: {{ ta_vie_body_family | json }}, "Hiragino Kaku Gothic ProN", "Yu Gothic", Meiryo, "Noto Sans CJK JP", sans-serif;
    font-weight: 400;
    font-style: normal;
    line-height: {{ ta_vie_body_line_height }};
    text-wrap: pretty;
  }

  {{ ta_vie_scope }} :is(.hero__rte, .hero__description, .column__text, .article__excerpt):not(.product-item, .product-item *, product-info, product-info *, .hero__products *, .hero__collections *) > p {
    line-height: inherit;
  }

  {{ ta_vie_scope }} :is(.hero__subheading, .subheading):not(.product-item, .product-item *, product-info, product-info *, .hero__products *, .hero__collections *) {
    font-family: {{ ta_vie_body_family | json }}, "Hiragino Kaku Gothic ProN", "Yu Gothic", Meiryo, "Noto Sans CJK JP", sans-serif;
    font-size: {{ ta_vie_subheading_size }}px;
    font-weight: 400;
    font-style: normal;
    letter-spacing: 0.12em;
    line-height: 1.6;
    text-transform: none;
  }
  {%- endif %}

  {{ ta_vie_wrap_scope }} :is(.hero__title, .text-products__heading, .blog__title):not(.product-item, .product-item *, product-info, product-info *, .hero__products *, .hero__collections *) {
    word-break: keep-all;
    overflow-wrap: break-word;
    line-break: strict;
  }
{%- endstyle -%}

{%- doc -%}
  Collect menu destinations, including nested links, to avoid duplicate navigation.
  @param {link[]} [links] - Existing menu links.
{%- enddoc -%}
{%- for menu_link in links -%}
  |{{- menu_link.url -}}|
  {%- if menu_link.type == 'page_link' or menu_link.type == 'blog_link' -%}
    |{{- menu_link.type -}}:{{- menu_link.object.id -}}|
  {%- endif -%}
  {%- if menu_link.links.size > 0 -%}
    {%- render 'ta-vie-menu-destinations', links: menu_link.links -%}
  {%- endif -%}
{%- endfor -%}

{%- comment -%}Product-owned copy; a shared template never supplies product facts.{%- endcomment -%}
{%- liquid
  assign feature = product.metafields.ta_vie.feature.value
  assign feature_owner = feature.owner_product.value
-%}
{%- if feature != blank and feature_owner.id == product.id and feature.lead.value != blank -%}
  <div class="product__block ta-vie-purchase__intro block-padding" {{ block_style }} {{ block.shopify_attributes }}>
    <p>{{ feature.lead.value | escape }}</p>
  </div>
{%- elsif request.design_mode -%}
  <div class="product__block block-padding ta-vie-purchase__editor-note" {{ block_style }} {{ block.shopify_attributes }}>
    <p>この商品の特集に「短いコピー」を設定すると表示されます。特集の「対象商品」も確認してください。</p>
  </div>
{%- endif -%}

{%- if section.settings.ta_vie_product_experience and featured_product == false -%}
  <span id="ta-vie-purchase-anchor" class="ta-vie-purchase__anchor" aria-hidden="true"></span>
{%- endif -%}

{%- if section.settings.ta_vie_product_experience and featured_product == false -%}
  {{ 'ta-vie-product-purchase.css' | asset_url | stylesheet_tag }}
  <script src="{{ 'ta-vie-product-purchase.js' | asset_url }}" defer="defer"></script>
{%- endif -%}

{%- if block.type == 'ta_vie_intro' -%}
  {%- render 'ta-vie-product-intro', product: product, block: block, block_style: block_style -%}
{%- else -%}
  {%- render 'product-block-text', block: block, block_style: block_style -%}
{%- endif -%}

{%- comment -%}
  Site-wide TA VIE typography using the existing body font and Japanese
  system fonts. Sizes, layout and the original font-picker values stay native.
{%- endcomment -%}
{%- liquid
  assign ta_vie_font_style = settings.ta_vie_japanese_font_style | default: 'sans'
  assign ta_vie_latin_family = settings.type_base_font.family | default: 'DM Sans'
-%}
{%- if ta_vie_font_style == 'sans' or ta_vie_font_style == 'serif' -%}
  {%- capture ta_vie_body_stack -%}{{ ta_vie_latin_family | json }}, "Hiragino Sans", "Hiragino Kaku Gothic ProN", "Yu Gothic", YuGothic, "Noto Sans CJK JP", Meiryo, sans-serif{%- endcapture -%}
  {%- style -%}
    :root {
      --FONT-STACK-BODY: {{ ta_vie_body_stack }};
      --FONT-STACK-NAV: {{ ta_vie_body_stack }};
      --FONT-STACK-SUBHEADING: {{ ta_vie_body_stack }};
      --BTN-FONT-STACK: {{ ta_vie_body_stack }};
      {%- if ta_vie_font_style == 'serif' %}
      --FONT-STACK-HEADING: Georgia, "Times New Roman", "Hiragino Mincho ProN", "Yu Mincho", YuMincho, "Noto Serif CJK JP", serif;
      {%- else %}
      --FONT-STACK-HEADING: {{ ta_vie_body_stack }};
      {%- endif %}
      --FONT-WEIGHT-HEADING: 400;
      --FONT-STYLE-HEADING: normal;
      --FONT-UPPERCASE-HEADING: none;
    }
  {%- endstyle -%}
{%- endif -%}

